vec3 ShaneResp(vec2 uv)
{
    //By Shane 
    uv*=0.25;
    // Slight screen warp.
    // *= .95 + dot(uv, uv)*.1;

    // Scaling and smoothing factor.
    float sf = 8./iResolution.y;
    vec2 p = uv*8. + vec2(2, 1)*iTime/2.;

    // Shift every second row across two units, so the green
    // squares have a checkered arrangement.
    if(mod(floor(p.y), 2.)<.5) p.x += 2.;

    // ID and local coordinates.
    vec2 ip = floor(p);
    p -= ip + .5;

    // Wrap every 4 units.
    ip = mod(ip, 4.);

    // Border value.
    float bord = 1.;


    //mat3x3 c = mat3x3(vec3(.9), vec3(.1), vec3(.5));
    mat3x3 c = mat3x3(vec3(1, .9, .4), vec3(.4, 1, .4), vec3(1, .1, .9));

    vec3 col = c[0]; // Yellow. No borders.


    if(ip.x == 2.){
       col = c[1];  // Green.     
       bord = abs(abs(p.y) - .5); // Upper and lower borders.
       bord = min(bord, abs(abs(p.x) - .5)); // Upper and lower borders.

    }
    else if((ip.x == 1. && -p.x<p.y) || (ip.x == 3. && p.x<-p.y)){

       col = c[2]; // Purple.

       // Diagonal and side borders.
       bord = abs(p.x + p.y)/sqrt(2.);
       bord = min(bord, abs(abs(p.x) - .5));

    }
    else {

        if(ip.x!=0.) bord = abs(p.x + p.y)/sqrt(2.);
        bord = min(bord, abs(abs(p.y) - .5)); // Upper and lower borders.

    }


    float shade = 1. - smoothstep(0., .1, bord);

    // Border thickness.
    bord -= .02;


    col = mix(col*(.9 + shade*2.), vec3(0), 1. - smoothstep(0., sf, bord));

    // Rough gamma correction.
    //fragColor = vec4(sqrt(max(col, 0.)), 1);
    col=sqrt(max(col, 0.));
    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float scale = 2.0;
    vec2 uv = scale * (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    uv+=iTime*0.5;
    vec2 uv0=uv;

    vec3 col = vec3(0.0);
    float tileSize = 1.0;


    // Posición del tile
    vec2 tilePos = floor(uv / tileSize);
    vec2 localPos = fract(uv / tileSize);

    // Desplazamiento continuo acumulado en las filas

    tilePos.y += tilePos.y * 1.0; // Cada fila se desplaza un poco más que la anterior

    // Alternar entre fig1 y fig2
    if (mod(floor(tilePos.x), 2.0) == 0.0) {

        col = fig1(localPos, col);  // Figura 1
    } else {
        col = fig2(localPos, col);  // Figura 2
    }


    // Corrección de gamma
    if(3.0*sin(iTime)>0.0)
    col = pow(col, vec3(0.4545));  // Corrección de gamma para colores
    else
        col= ShaneResp(uv0);


    fragColor = vec4(col, 1.0);
}

